/* @lc app=leetcode id=1900 lang=kotlin */
class Solution { fun earliestAndLatest(n: Int, f: Int, s: Int): IntArray = if (f + s == n + 1) intArrayOf(1, 1) else if (n <= 4) intArrayOf(2, 2) else if (minOf(f, s) - 1 > n - maxOf(f, s)) earliestAndLatest(n, n + 1 - maxOf(f, s), n + 1 - minOf(f, s)) else (0 until minOf(f, s)).flatMap { i -> (0..if (maxOf(f, s) * 2 <= n + 1) maxOf(f, s) - minOf(f, s) - 1 else n + 1 - maxOf(f, s) - minOf(f, s) - 1).map { j -> earliestAndLatest((n + 1) / 2, i + 1, if (maxOf(f, s) * 2 <= n + 1) i + j + 2 else i + j + 1 + (maxOf(f, s) - (n + 1 - maxOf(f, s))) / 2 + 1) } }.fold(intArrayOf(Int.MAX_VALUE, Int.MIN_VALUE)) { a, b -> intArrayOf(minOf(a[0], b[0] + 1), maxOf(a[1], b[1] + 1)) } }